function validate([heights, volume, k]) {
  if (!Array.isArray(heights) || heights.length < 1 || heights.length > 100) return 'heights needs 1 to 100 columns.';
  if (heights.some(v => !Number.isInteger(v) || v < 0 || v > 99)) return 'Each height is a whole number from 0 to 99.';
  if (!Number.isInteger(volume) || volume < 0 || volume > 2000) return 'volume is between 0 and 2000.';
  if (!Number.isInteger(k) || k < 0 || k >= heights.length) return 'k must be an index of heights.';
  return null;
}

