function pourWater(heights, volume, k) {
  const levels = heights.slice();
  for (let drop = 0; drop < volume; drop++) {
    let target = k;
    for (const step of [-1, 1]) {
      let i = k;
      while (i + step >= 0 && i + step < levels.length && levels[i + step] <= levels[i]) {
        if (levels[i + step] < levels[i]) {
          target = i + step;
        }
        i += step;
      }
      if (target !== k) {
        break;
      }
    }
    levels[target]++;
  }
  return levels;
}

