function pourWater(heights, volume, k) {
  const h = [...heights];
  // Collect every column the unit can walk to in one direction, then pick the lowest, nearest one.
  const settle = (dir) => {
    const reach = [];
    for (let j = k + dir; j >= 0 && j < h.length && h[j] <= h[j - dir]; j += dir) reach.push(j);
    let best = -1;
    for (const j of reach) {
      if (h[j] < h[k] && (best === -1 || h[j] < h[best])) best = j;
    }
    return best;
  };
  for (let t = 0; t < volume; t++) {
    let spot = settle(-1);
    if (spot === -1) spot = settle(1);
    if (spot === -1) spot = k;
    h[spot] += 1;
  }
  return h;
}

