function generate(rand, size) {
  const pick = (m) => Math.floor(rand() * m);
  if (size === 'large') {
    const n = 60 + pick(41);
    const shape = pick(3);
    const heights = Array.from({ length: n }, (_, i) => {
      if (shape === 0) return pick(100);
      if (shape === 1) return Math.min(99, Math.abs(i - Math.floor(n / 2)) * 2 + pick(5));
      return Math.floor(50 + 45 * Math.sin(i / 4)) + pick(3);
    });
    return [heights, 1000 + pick(1001), pick(n)];
  }
  const n = 1 + pick(8);
  const top = 1 + pick(6);
  const heights = Array.from({ length: n }, () => pick(top));
  return [heights, pick(16), pick(n)];
}
